HT='''/// 🧊️ Fills a text list of numbers in its original vector.
fn numbers_text_into(output:&mut Vec<f64>,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::text_list_into(output,value,control,limits,entities,Default::default,|slot,value,control,_|{*slot=native::float(value,control)?;Ok(())})}
/// 🧊️ Fills a text list of spatial points in its original vector.
fn points3_text_into(output:&mut Vec<SemioPoint3>,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::text_list_into(output,value,control,limits,entities,Default::default,|slot,value,control,_|{*slot=point3_text(value,control)?;Ok(())})}
/// 🧊️ Fills a text list of parametric points in its original vector.
fn points2_text_into(output:&mut Vec<SemioPoint2>,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::text_list_into(output,value,control,limits,entities,Default::default,|slot,value,control,_|{*slot=point2_text(value,control)?;Ok(())})}
/// 🧊️ Selects each text curve variant in its retained slot before filling its spline arrays.
fn curve_text_into(output:&mut BrepCurve,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"BRep native curve tag missing"))?;match tag{
"L"=>{let[origin,direction]=native::record(value,control)?;*output=BrepCurve::Line{origin:point3_text(origin,control)?,direction:point3_text(direction,control)?};},
"C"=>{let[center,axis,radius]=native::record(value,control)?;*output=BrepCurve::Circle{center:point3_text(center,control)?,axis:point3_text(axis,control)?,radius:native::float(radius,control)?};},
"E"=>{let[center,axis,radius_major,radius_minor]=native::record(value,control)?;*output=BrepCurve::Ellipse{center:point3_text(center,control)?,axis:point3_text(axis,control)?,radius_major:native::float(radius_major,control)?,radius_minor:native::float(radius_minor,control)?};},
"N"=>{let[point_fields,weight_fields,degree_field,knot_fields]=native::record(value,control)?;*output=BrepCurve::Nurbs{control_points:Vec::new(),weights:Vec::new(),degree:0,knots:Vec::new()};let BrepCurve::Nurbs{control_points,weights,degree,knots}=&mut *output else{unreachable!()};points3_text_into(control_points,point_fields,control,limits,entities)?;numbers_text_into(weights,weight_fields,control,limits,entities)?;*degree=u32_text(degree_field,control)?;numbers_text_into(knots,knot_fields,control,limits,entities)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep native curve kind"))}Ok(())}
/// 🧊️ Selects each text p-curve variant in its retained slot before filling its spline arrays.
fn curve2_text_into(output:&mut BrepCurve2,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"BRep native p-curve tag missing"))?;match tag{
"L"=>{let[origin,direction]=native::record(value,control)?;*output=BrepCurve2::Line{origin:point2_text(origin,control)?,direction:point2_text(direction,control)?};},
"C"=>{let[center,radius]=native::record(value,control)?;*output=BrepCurve2::Circle{center:point2_text(center,control)?,radius:native::float(radius,control)?};},
"E"=>{let[center,x_axis,radius_major,radius_minor]=native::record(value,control)?;*output=BrepCurve2::Ellipse{center:point2_text(center,control)?,x_axis:point2_text(x_axis,control)?,radius_major:native::float(radius_major,control)?,radius_minor:native::float(radius_minor,control)?};},
"N"=>{let[point_fields,weight_fields,degree_field,knot_fields]=native::record(value,control)?;*output=BrepCurve2::Nurbs{control_points:Vec::new(),weights:Vec::new(),degree:0,knots:Vec::new()};let BrepCurve2::Nurbs{control_points,weights,degree,knots}=&mut *output else{unreachable!()};points2_text_into(control_points,point_fields,control,limits,entities)?;numbers_text_into(weights,weight_fields,control,limits,entities)?;*degree=u32_text(degree_field,control)?;numbers_text_into(knots,knot_fields,control,limits,entities)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep native p-curve kind"))}Ok(())}
/// 🧊️ Selects each text surface variant in its retained slot before filling its spline arrays.
fn surface_text_into(output:&mut BrepSurface,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"BRep native surface tag missing"))?;match tag{
"P"=>{let[origin,normal]=native::record(value,control)?;*output=BrepSurface::Plane{origin:point3_text(origin,control)?,normal:point3_text(normal,control)?};},
"C"=>{let[origin,axis,radius]=native::record(value,control)?;*output=BrepSurface::Cylinder{origin:point3_text(origin,control)?,axis:point3_text(axis,control)?,radius:native::float(radius,control)?};},
"O"=>{let[origin,axis,radius,half_angle]=native::record(value,control)?;*output=BrepSurface::Cone{origin:point3_text(origin,control)?,axis:point3_text(axis,control)?,radius:native::float(radius,control)?,half_angle:native::float(half_angle,control)?};},
"S"=>{let[center,radius]=native::record(value,control)?;*output=BrepSurface::Sphere{center:point3_text(center,control)?,radius:native::float(radius,control)?};},
"T"=>{let[center,axis,major_radius,minor_radius]=native::record(value,control)?;*output=BrepSurface::Torus{center:point3_text(center,control)?,axis:point3_text(axis,control)?,major_radius:native::float(major_radius,control)?,minor_radius:native::float(minor_radius,control)?};},
"N"=>{let[point_fields,weight_fields,u_field,v_field,degree_u_field,degree_v_field,knot_u_fields,knot_v_fields]=native::record(value,control)?;*output=BrepSurface::Nurbs{control_points:Vec::new(),weights:Vec::new(),u_count:0,v_count:0,degree_u:0,degree_v:0,knots_u:Vec::new(),knots_v:Vec::new()};let BrepSurface::Nurbs{control_points,weights,u_count,v_count,degree_u,degree_v,knots_u,knots_v}=&mut *output else{unreachable!()};points3_text_into(control_points,point_fields,control,limits,entities)?;numbers_text_into(weights,weight_fields,control,limits,entities)?;*u_count=u32_text(u_field,control)?;*v_count=u32_text(v_field,control)?;*degree_u=u32_text(degree_u_field,control)?;*degree_v=u32_text(degree_v_field,control)?;numbers_text_into(knots_u,knot_u_fields,control,limits,entities)?;numbers_text_into(knots_v,knot_v_fields,control,limits,entities)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep native surface kind"))}Ok(())}
'''
D='''/// 📝️ Fills the retained BRep root from the borrowed document body, inserting every topology entity before its identifiers and geometry.
pub fn document_into(output:&mut SemioBrepSnapshot,body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_document(body,control,limits)?;let fields=native::fields(body,["schema","vertices","edges","loops","faces","shells","solids","coedges","nextLabel"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;native::hex_text_into(&mut output.schema,fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"BRep native schema missing"))?,control)?;
 native::text_list_into(&mut output.vertices,fields[1].unwrap_or("[]"),control,limits,&mut entities,Default::default,|vertex,value,control,_|{let[id,point,tol]=native::record(value,control)?;native::hex_text_into(&mut vertex.id,id,control)?;vertex.point=point3_text(point,control)?;vertex.tol=native::float(tol,control)?;Ok(())})?;
 native::text_list_into(&mut output.edges,fields[2].unwrap_or("[]"),control,limits,&mut entities,Default::default,|edge,value,control,entities|{let[id,start_vertex,end_vertex,curve,tol]=native::record(value,control)?;native::hex_text_into(&mut edge.id,id,control)?;native::hex_text_into(&mut edge.start_vertex,start_vertex,control)?;native::hex_text_into(&mut edge.end_vertex,end_vertex,control)?;curve_text_into(&mut edge.curve,curve,control,limits,entities)?;edge.tol=native::float(tol,control)?;Ok(())})?;
 native::text_list_into(&mut output.loops,fields[3].unwrap_or("[]"),control,limits,&mut entities,Default::default,|brep_loop,value,control,entities|{let[id,edges]=native::record(value,control)?;native::hex_text_into(&mut brep_loop.id,id,control)?;native::text_list_into(&mut brep_loop.edges,edges,control,limits,entities,Default::default,|member,value,control,_|{let[edge,orientation]=native::record(value,control)?;native::hex_text_into(&mut member.edge,edge,control)?;member.orientation=bool_text(orientation)?;Ok(())})})?;
 native::text_list_into(&mut output.faces,fields[4].unwrap_or("[]"),control,limits,&mut entities,Default::default,|face,value,control,entities|{let[id,outer_loop,inner_loops,surface,orientation,tol]=native::record(value,control)?;native::hex_text_into(&mut face.id,id,control)?;native::hex_text_into(&mut face.outer_loop,outer_loop,control)?;native::text_list_into(&mut face.inner_loops,inner_loops,control,limits,entities,Default::default,|slot,value,control,_|{let[id]=native::record(value,control)?;native::hex_text_into(slot,id,control)})?;surface_text_into(&mut face.surface,surface,control,limits,entities)?;face.orientation=bool_text(orientation)?;face.tol=native::float(tol,control)?;Ok(())})?;
 native::text_list_into(&mut output.shells,fields[5].unwrap_or("[]"),control,limits,&mut entities,Default::default,|shell,value,control,entities|{let[id,faces]=native::record(value,control)?;native::hex_text_into(&mut shell.id,id,control)?;native::text_list_into(&mut shell.faces,faces,control,limits,entities,Default::default,|member,value,control,_|{let[face,orientation]=native::record(value,control)?;native::hex_text_into(&mut member.face,face,control)?;member.orientation=bool_text(orientation)?;Ok(())})})?;
 native::text_list_into(&mut output.solids,fields[6].unwrap_or("[]"),control,limits,&mut entities,Default::default,|solid,value,control,entities|{let[id,shells]=native::record(value,control)?;native::hex_text_into(&mut solid.id,id,control)?;native::text_list_into(&mut solid.shells,shells,control,limits,entities,Default::default,|member,value,control,_|{let[shell,is_void]=native::record(value,control)?;native::hex_text_into(&mut member.shell,shell,control)?;member.is_void=bool_text(is_void)?;Ok(())})})?;
 native::text_list_into(&mut output.coedges,fields[7].unwrap_or("[]"),control,limits,&mut entities,Default::default,|coedge,value,control,entities|{let[id,edge,forward,pcurve,prange,loop_id,next,prev]=native::record(value,control)?;native::hex_text_into(&mut coedge.id,id,control)?;native::hex_text_into(&mut coedge.edge,edge,control)?;coedge.forward=bool_text(forward)?;if pcurve!="-"{curve2_text_into(coedge.pcurve.insert(BrepCurve2::default()),pcurve.strip_prefix('~').ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep native optional p-curve"))?,control,limits,entities)?;}let[a,b]=native::record(prange,control)?;coedge.prange=(native::float(a,control)?,native::float(b,control)?);native::hex_text_into(&mut coedge.loop_id,loop_id,control)?;native::hex_text_into(&mut coedge.next,next,control)?;native::hex_text_into(&mut coedge.prev,prev,control)})?;
 let next_label=fields[8].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"BRep native nextLabel missing"))?;output.next_label=control.scoped_stage(|control|{control.begin_stage(next_label.len())?;for _ in next_label.bytes(){control.step()?;}next_label.parse::<u64>().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep native unsigned64 label"))})?;Ok(())}
'''
p=rs.native("🧊️brep")
print(dom.apply("🧊️brep",B,D,remove=("numbers_binary","curve_binary","curve2_binary","surface_binary","numbers_text","curve_text","curve2_text","surface_text")))
s=open(p,encoding="utf-8").read()
s=s.replace("/// 🧩️ Fills the retained BRep root",HB+"/// 🧩️ Fills the retained BRep root",1)
s=s.replace("/// 📝️ Fills the retained BRep root",HT+"/// 📝️ Fills the retained BRep root",1)
open(p,"w",encoding="utf-8").write(s)
print(dom.fmt("🧊️brep"))
